package com.ethk3.novaonepro.r952;
import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import java.nio.file.*;import java.io.*;import java.util.*;
/** Actual full pinned immutable spec registration and resume/CAS on canonical SQLite. No manually inserted Atom rows. */
public final class AtomCatalogImportCP12Test {
 static int checks;static void ok(boolean x){checks++;if(!x)throw new AssertionError("import "+checks);}static void tx(SQLiteDatabase db,Runnable body,boolean commit){db.beginTransaction();try{body.run();if(commit)db.setTransactionSuccessful();}finally{db.endTransaction();}}static AtomCatalogImportCP12.Page prepare(Path path,AtomCatalogImportCP12.ImportCursor c)throws Exception{FileInputStream f=new FileInputStream(path.toFile());f.getChannel().position(c.offset);try{return AtomCatalogImportCP12.preparePageCP12(f,c,System.nanoTime()+60_000_000_000L);}finally{f.close();}}
 public static void main(String[] args)throws Exception{SQLiteDatabase db=new SQLiteDatabase(args[0],args[1]);Path asset=Path.of(args[2]);try{ok(!AtomCatalogImportCP12.completeCP12(db));tx(db,()->AtomCatalogImportCP12.schemaCP12(db),true);ok(!AtomCatalogImportCP12.completeCP12(db));AtomCatalogImportCP12.ImportCursor cursor=AtomCatalogImportCP12.readCursorCP12(db);ok(cursor.row==0&&cursor.offset==0);AtomCatalogImportCP12.Page first=prepare(asset,cursor);ok(first.rows.size()==32);tx(db,()->AtomCatalogImportCP12.applyPageCP12(db,first,1),false);ok(AtomCatalogImportCP12.readCursorCP12(db).row==0);try(Cursor c=db.rawQuery("SELECT COUNT(*) FROM research_atom_spec_v2",null)){c.moveToFirst();ok(c.getInt(0)==0);}tx(db,()->AtomCatalogImportCP12.applyPageCP12(db,first,2),true);tx(db,()->AtomCatalogImportCP12.applyPageCP12(db,first,3),true);ok(AtomCatalogImportCP12.readCursorCP12(db).row==32);AtomCatalogImportCP12.Page second=prepare(asset,AtomCatalogImportCP12.readCursorCP12(db));tx(db,()->AtomCatalogImportCP12.applyPageCP12(db,second,4),true);boolean stale=false;db.beginTransaction();try{AtomCatalogImportCP12.applyPageCP12(db,first,5);db.setTransactionSuccessful();}catch(IllegalStateException bad){stale=bad.getMessage().equals("ATOM_IMPORT_CURSOR_CAS");}finally{db.endTransaction();}ok(stale);
  AtomCatalogImportCP12.Page next=prepare(asset,AtomCatalogImportCP12.readCursorCP12(db));AtomSpecCP4 s=next.rows.get(0);db.execSQL("INSERT INTO research_atom_spec_v2 VALUES(?,?,?,?,?,?,?,?,?,?)",new Object[]{s.atomId,s.family,s.version,s.canonicalSpec,s.position,"BROKEN_TYPE",s.minimumHistory,s.specHash,s.missingPolicy,s.state});boolean conflict=false;db.beginTransaction();try{AtomCatalogImportCP12.applyPageCP12(db,next,6);db.setTransactionSuccessful();}catch(IllegalStateException bad){conflict=bad.getMessage().equals("ATOM_IMPORT_IMMUTABLE_SPEC_CONFLICT");}finally{db.endTransaction();}ok(conflict&&AtomCatalogImportCP12.readCursorCP12(db).row==64);db.execSQL("DELETE FROM research_atom_spec_v2 WHERE atom_id=?",new String[]{s.atomId});
  int pages=2;long start=System.nanoTime();while(!AtomCatalogImportCP12.completeCP12(db)){AtomCatalogImportCP12.ImportCursor before=AtomCatalogImportCP12.readCursorCP12(db);if(AtomCatalogPinnedCP12.ROWS-before.row<=32){byte[] tail;try(FileInputStream f=new FileInputStream(asset.toFile())){f.getChannel().position(before.offset);tail=f.readAllBytes();}String[] lines=new String(tail,java.nio.charset.StandardCharsets.UTF_8).split("\n");StringBuilder changed=new StringBuilder();for(int i=lines.length-1;i>=0;i--)changed.append(lines[i]).append('\n');boolean shaRejected=false;try{AtomCatalogImportCP12.preparePageCP12(new ByteArrayInputStream(changed.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)),before,System.nanoTime()+60_000_000_000L);}catch(IllegalStateException bad){shaRejected=bad.getMessage().equals("ATOM_CATALOG_FULL_SHA256");}ok(shaRejected&&AtomCatalogImportCP12.readCursorCP12(db).row==before.row);}AtomCatalogImportCP12.Page page=prepare(asset,before);ok(page!=null&&page.rows.size()<=32&&page.after.offset-page.before.offset<=65536);tx(db,()->AtomCatalogImportCP12.applyPageCP12(db,page,10),true);pages++;}
  AtomCatalogImportCP12.ImportCursor done=AtomCatalogImportCP12.readCursorCP12(db);ok(done.row==AtomCatalogPinnedCP12.ROWS&&done.offset==AtomCatalogPinnedCP12.BYTES&&done.prefixHash.equals(AtomCatalogPinnedCP12.SHA256));try(Cursor c=db.rawQuery("SELECT COUNT(*),COUNT(DISTINCT spec_hash) FROM research_atom_spec_v2",null)){c.moveToFirst();ok(c.getInt(0)==AtomCatalogPinnedCP12.ROWS&&c.getInt(1)==AtomCatalogPinnedCP12.ROWS);}try(Cursor c=db.rawQuery("PRAGMA foreign_key_check",null)){ok(!c.moveToFirst());}System.out.println("CP12_ATOM_CATALOG_IMPORT_PASS checks="+checks+" rows="+done.row+" pages="+pages+" bytes="+done.offset+" EOF_SHA="+done.prefixHash+" rollback=PASS replay=PASS staleCAS=PASS typeConflict=PASS actualColdRegistry=PASS elapsedHostMs="+(System.nanoTime()-start)/1e6);
 }finally{db.shutdown();}}
}
